content:
{
  "guide": {
    "schema_version": "optomind.guided_body_guide.v1",
    "manuscript_guide": "全文按“临床关联证据→免疫机制→代谢物中介→外部干扰→干预转化→毒性管理→方法学未来”推进。Ch1 主讲观察性关联的强度、异质性、外部修饰与证据阶梯；Ch2 主讲免疫机制链条并严格区分动物因果与人类关联；Ch3 主讲代谢物分子靶点与 TME 浓度缺口；Ch4 主讲抗生素/PPI/饮食等外部暴露的时机、剂量与癌种差异；Ch5 主讲 FMT/LBP/益生菌干预的证据等级、初治与难治差异、安全性边界；Ch6 主讲 irAE 微生物预测、疗效-毒性耦合/解耦与供体-方案情境安全；Ch7 主讲技术标准化、因果推断、III 期缺口与未来设计。重复案例采用分层复用：FMT-LUMINate 在 Ch1 作为证据阶梯案例，在 Ch2 作为人类伴随机制线索，在 Ch5 作为初治干预主讲案例，在 Ch6 作为供体毒性主讲案例；MITRIC 在 Ch1 作为阴性对照，在 Ch5 作为难治人群主讲案例；JCOG2007 在 Ch1 主讲方案特异性，在 Ch4 作为化疗时序修饰对照，在 Ch5 仅作背景。写作中保留阴性结果、条件限定、样本量限制与证据等级标注。全文实际引用目标为去重后不少于 150 篇；相关来源可在背景、方法、解释与比较中共同引用，合并论述时保留各自支撑作用。",
    "chapters": [
      {
        "chapter_id": "Ch1",
        "title": "实体瘤中肠道微生物组与 ICI 疗效的临床关联证据",
        "writing_arrangement": "本章先建立跨癌种观察性关联的总体图景，再立即用统计与反例限制“通用标志物”推断；随后引入外部药物暴露与治疗方案作为修饰变量，再转向纵向动态对基线快照的补充，最后以证据阶梯收束。解释顺序为：共性信号→异质性与无通用标志物→方案/暴露修饰→纵向动态→证据等级与转化边界。写作中每次引用具体数字时标明研究设计、癌种、治疗方案与时间窗；对 FMT-LUMINate、MITRIC、MIMic、JCOG2007 等案例只作本章所需的证据等级展示，不展开后续章节的机制与安全性细节。",
        "required_content": [
          "章首用一段说明本章只评估临床关联与证据等级，机制细节留给 Ch2/Ch3，外部因素系统展开留给 Ch4，干预试验系统评价留给 Ch5。",
          "在证据阶梯单元中明确表格承担的比较：试验阶段、目标人群、干预策略、疗效结果与关键局限；正文解释表格而不是重复表格。",
          "保留 P0289、P0275、P0270、P0327 等阴性或反例证据，避免将观察性关联写成普适结论。"
        ],
        "source_handles": [],
        "writing_units": [
          {
            "unit_id": "Ch1_W1",
            "title": "跨癌种关联图谱与无通用标志物的统计依据",
            "writing_arrangement": "先写黑色素瘤、NSCLC、RCC 等队列中反复出现的分类学与功能信号，再写 HCC、mCRPC、结直肠癌等信号失效或反转，随后用跨队列 PERMANOVA、机器学习泛化差、肠型特异性与功能趋同解释为何没有普适单一标志物。最后以 JCOG2007 的方案特异性作为过渡，说明关联方向受治疗方案修饰。",
            "content_task_ids": ["C0001", "C0002", "C0003"],
            "source_handles": []
          },
          {
            "unit_id": "Ch1_W2",
            "title": "外部药物暴露与宿主背景对关联强度的修饰",
            "writing_arrangement": "本单元量化抗生素与 PPIs 的效应量和时间窗，比较不同癌种与人群中的阳性/阴性结果，再讨论联合方案对微生物效应方向的反转或放大。最后写校正必要性、指示偏倚与残余偏倚，为 Ch4 的系统展开留出接口但不重复其全部机制。",
            "content_task_ids": ["C0004", "C0005", "C0006"],
            "source_handles": []
          },
          {
            "unit_id": "Ch1_W3",
            "title": "基线快照局限与纵向动态的预测价值",
            "writing_arrangement": "从基线单次采样无法捕捉治疗诱导生态重塑写起，比较新辅助与晚期疾病中稳定性/多样性信号的差异；再写纵向动态（有害菌丢失、定植、稳定性丧失、多组学轨迹）的预测价值；最后写采样频率、存储、标准化与参考值缺失等方法学障碍。此处只作临床观察层面的动态证据，不展开机制。",
            "content_task_ids": ["C0007", "C0008", "C0009"],
            "source_handles": []
          },
          {
            "unit_id": "Ch1_W4",
            "title": "证据阶梯、阴性干预与安全信号的情境依赖",
            "writing_arrangement": "总结观察性证据最强、概念验证干预异质性大、Phase III 缺失的证据阶梯；比较 FMT-LUMINate 阳性、MITRIC 阴性与早期综述/荟萃证据；用表格呈现主要干预试验设计与局限；最后用安全信号仅在双 ICI 背景出现说明方案调节，并过渡到下一章机制。",
            "content_task_ids": ["C0010", "C0011", "C0012", "C0013"],
            "source_handles": []
          }
        ]
      },
      {
        "chapter_id": "Ch2",
        "title": "微生物调节 ICI 疗效的免疫学机制",
        "writing_arrangement": "本章建立“微生物信号→先天识别→适应性启动→屏障/易位/髓系重塑→肿瘤类型与模型边界”的机制链。每个机制节点都按“动物因果证据→人类关联/伴随证据→外推限制”组织。与 Ch1 的衔接是：Ch1 已证明关联存在但非普适，本章解释可能机制；与 Ch3 的分工是：本章写细胞与受体通路，不深入代谢物浓度/剂量；与 Ch5/Ch6 的分工是：本章不评价干预试验成败，只在必要处引用人类试验作为伴随证据。",
        "required_content": [
          "每个机制段落标注证据类型：小鼠因果、体外功能、人类宏基因组关联、人类干预伴随观察。",
          "保留 CRC、PDAC、消化道肿瘤等语境差异，防止 PRR/STING/屏障机制被写成单向促免疫。",
          "表格承担不同肿瘤类型中关键微生物特征、机制通路、证据类型与来源比较；正文解释差异含义。"
        ],
        "source_handles": [],
        "writing_units": [
          {
            "unit_id": "Ch2_W1",
            "title": "先天识别与 DC 启动：结构、受体与检查点语气",
            "writing_arrangement": "先写 LPS 酰化状态、MAMPs/TLR/NOD2 等结构-受体语境，说明“有菌不等于激活”；再写 DC 亚群成熟、迁移与 STING/IFN-β 轴；最后写微生物调节 DC PD-L2/RGMb 等检查点语气。人类证据用黑色素瘤 lpxM 关联、FMT 后 CD8+ 增加与肿瘤内微生物观察作对照，强调不能直接外推小鼠因果。",
            "content_task_ids": ["C0014", "C0015", "C0016"],
            "source_handles": []
          },
          {
            "unit_id": "Ch2_W2",
            "title": "适应性免疫启动：分子模拟、T 细胞 priming 与亚群平衡",
            "writing_arrangement": "先写分子模拟与交叉反应性 CD8+ 激活，区分小鼠功能回补与人类生物信息学/体外证据；再写 T 细胞 priming、Th17/Treg、非经典 T 细胞与耗竭调控。代谢物只作为微环境因素点名，详细分子靶点留给 Ch3。",
            "content_task_ids": ["C0017", "C0018"],
            "source_handles": []
          },
          {
            "unit_id": "Ch2_W3",
            "title": "屏障、细菌易位与髓系重编程的条件链",
            "writing_arrangement": "按“屏障状态→主动易位→髓系后果→人类情境”写。先用肠芯片与 P. bifermentans 说明屏障损伤与疗效增强可分离；再写 ICT 诱导 DC/CCR7 依赖易位；随后写易位后髓系重编程决定免疫方向；最后用 FMT-LUMINate 与综述异质性说明人类证据的情境依赖。",
            "content_task_ids": ["C0019", "C0020", "C0021", "C0022"],
            "source_handles": []
          },
          {
            "unit_id": "Ch2_W4",
            "title": "肿瘤类型特异性与模型系统差异",
            "writing_arrangement": "比较黑色素瘤、NSCLC、RCC、HCC、mCRPC、TNBC、消化道肿瘤与下呼吸道/肿瘤内微生物证据，说明机制表达受肿瘤背景、治疗史与部位影响。最后严格总结临床前因果与人类观察性证据的边界，并用表格承载跨肿瘤比较。",
            "content_task_ids": ["C0023", "C0024", "C0025"],
            "source_handles": []
          }
        ]
      },
      {
        "chapter_id": "Ch3",
        "title": "微生物代谢物的中介作用与分子机制",
        "writing_arrangement": "本章按四大代谢物类别展开，但统一采用“分子靶点→证据层级→情境依赖→浓度/递送缺口”的写法。Ch2 已写免疫细胞通路，本章聚焦代谢物本身：SCFAs 的 HDAC/GPCR 双向效应；肌苷的 UBA6/A2AR/碳源区分；胆汁酸与色氨酸代谢物的核受体网络；功能通路与表观遗传整合。最后集中讨论血浆/粪便代理与人体 TME 浓度缺失。写作中严格区分血浆、粪便、体外设定浓度与人体组织实测值。",
        "required_content": [
          "每个代谢物单元标明证据来源是血浆/粪便关联、动物机制还是体外浓度实验。",
          "肌苷部分必须保留 CheckMate 025 血浆关联、UBA6 机制、II 期随机数据与 TME 实测缺失之间的层级差异。",
          "最后单元提出微透析、空间代谢组学、配对组织-血液采样等未来路线，但不写成过度承诺。"
        ],
        "source_handles": [],
        "writing_units": [
          {
            "unit_id": "Ch3_W1",
            "title": "SCFAs：HDAC/GPCR 双通路与 ICI 靶点依赖的双向效应",
            "writing_arrangement": "先写丁酸/丙酸/乙酸的基础生化路径；再写抗 PD-1 背景下高粪便 SCFA 与 PFS/响应的正向关联；随后写抗 CTLA-4 背景下的负面或限制性证据；最后写缺氧、浓度阈值与肿瘤细胞逆向摄取导致效应反转。",
            "content_task_ids": ["C0026", "C0027", "C0028", "C0029"],
            "source_handles": []
          },
          {
            "unit_id": "Ch3_W2",
            "title": "肌苷：UBA6 抑制、T 细胞外在作用与临床关联",
            "writing_arrangement": "先写肌苷结合/抑制 UBA6 的生化与遗传学证据；再写 CheckMate 025 血浆肌苷与 OS 关联及随机 II 期 PFS 信号；随后区分肿瘤内在 UBA6 作用与 T 细胞 A2AR/碳源作用；最后明确人体 TME 实测浓度缺失与药代挑战。",
            "content_task_ids": ["C0030", "C0031", "C0032", "C0033"],
            "source_handles": []
          },
          {
            "unit_id": "Ch3_W3",
            "title": "次级胆汁酸与色氨酸代谢物：核受体网络与系统/局部差异",
            "writing_arrangement": "先写 TDCA/UDCA 等通过 TGR5/FXR 增强 CD8+ 与巨噬细胞 M1 极化，并用 HCC 队列关联临床预后；再写 IPA、犬尿氨酸等通过 AhR/RORγt 调控 T 细胞与髓系；最后讨论肠道局部稳态与远端 TME 重塑中的剂量/分布差异。",
            "content_task_ids": ["C0034", "C0035", "C0036"],
            "source_handles": []
          },
          {
            "unit_id": "Ch3_W4",
            "title": "功能通路、表观遗传整合与功能性评分的必要性",
            "writing_arrangement": "用 MEP/核黄素通路与 Vδ2/MAIT 活化说明功能通路优于单一分类学；再写代谢物通过 HDAC 抑制、染色质开放与能量代谢锁定免疫细胞表型；最后提出功能性菌群失调评分/多组学模型替代传统多样性指标，但保留验证限制。",
            "content_task_ids": ["C0037", "C0038", "C0039"],
            "source_handles": []
          },
          {
            "unit_id": "Ch3_W5",
            "title": "血浆/粪便代理的效能、TME 浓度缺口与未来测量路线",
            "writing_arrangement": "先客观评价血浆/粪便代谢组学的临床可行性与偏差；再以肌苷为核心剖析缺乏 TME 阈值如何阻碍剂量优化与体内复现；最后提出微透析、MALDI-MSI、配对组织-血液纵向采样与局部浓度-受体占有率-结局映射。",
            "content_task_ids": ["C0040", "C0041", "C0042"],
            "source_handles": []
          }
        ]
      },
      {
        "chapter_id": "Ch4",
        "title": "外部因素对微生物 - 免疫轴的干扰",
        "writing_arrangement": "本章系统展开 Ch1 已提示的外部干扰。顺序为抗生素→PPI→饮食/生活方式。每类因素按“效应量与时间窗→微生物机制假说→癌种/宿主修饰→因果边界与临床建议”组织。与 Ch1 的增量是：Ch1 只把外部暴露作为关联修饰变量，本章提供系统证据、机制假说与实践含义；与 Ch5 的分工是：本章写被动干扰与可修饰暴露，不评价主动微生物干预试验。",
        "required_content": [
          "抗生素部分保留 HCC 阴性结果与 PD-L1 分层，避免写成所有癌种一致负面。",
          "PPI 部分保留化疗时序修饰、口腔化易位与 H2B 对照，并区分疗效与毒性药物警戒信号。",
          "饮食/益生菌部分保留商业益生菌矛盾证据与食物基质优于补充剂的条件性结论。"
        ],
        "source_handles": [],
        "writing_units": [
          {
            "unit_id": "Ch4_W1",
            "title": "抗生素：时间窗、疗程剂量与癌种特异性",
            "writing_arrangement": "先界定 ICI 前后高危窗口并比较术前/术后暴露；再写疗程长度与广谱类别的剂量-反应关系；最后引入 HCC 阴性结果、肝硬化免疫缓冲与外推边界。",
            "content_task_ids": ["C0043", "C0044", "C0045"],
            "source_handles": []
          },
          {
            "unit_id": "Ch4_W2",
            "title": "PPIs：胃酸抑制、口腔化易位与抑酸药物选择",
            "writing_arrangement": "先量化 PPI 与 OS/PFS 的负相关及使用时窗；再写化疗近期暴露的修饰与口腔细菌易位/多样性丧失机制；最后比较 PPI 与 H2B，提出必须抑酸时的降级与监测建议。",
            "content_task_ids": ["C0046", "C0047", "C0048"],
            "source_handles": []
          },
          {
            "unit_id": "Ch4_W3",
            "title": "饮食、益生菌与生活方式：可塑性、菌株特异性与间接路径",
            "writing_arrangement": "先写高纤维/特定宏量营养素与产 SCFA 菌、PFS 的关联；再写商业益生菌的矛盾证据、菌株特异性、生态位竞争与食物基质原则；最后简述昼夜节律/心理压力的神经内分泌-色氨酸路径，并标注证据层级。",
            "content_task_ids": ["C0049", "C0050", "C0051"],
            "source_handles": []
          }
        ]
      },
      {
        "chapter_id": "Ch5",
        "title": "微生物干预策略的临床转化现状",
        "writing_arrangement": "本章从“观察性关联”转向“因果性干预”的临床评估。顺序为初治人群阳性信号→难治人群阴性边界→定义菌株制剂→安全性→证据等级与转化瓶颈。与 Ch1 的增量是：Ch1 只展示证据阶梯概览，本章系统比较试验设计、人群、供体、机制假说与失败原因；与 Ch6 的分工是：本章写干预安全性作为转化边界，Ch6 写 irAE 预测与管理；与 Ch7 的分工是：本章提出瓶颈，Ch7 提供方法学设计原则。",
        "required_content": [
          "FMT-LUMINate 在本章主讲初治疗效与有害菌清除机制，但毒性细节主要留给 Ch6；本章只保留安全性 boundary。",
          "MITRIC 必须作为难治人群主讲阴性案例，解释快速进展、定植短暂与髓系主导微环境。",
          "明确目前没有已完成大型 Phase III RCT 支持常规临床应用；TACITO 作为早期随机但未达主要终点的对照。"
        ],
        "source_handles": [],
        "writing_units": [
          {
            "unit_id": "Ch5_W1",
            "title": "初治人群：FMT 联合一线 ICI 的缓解信号与机制假说",
            "writing_arrangement": "报告 FMT-LUMINate 与 MIMic 的 ORR/PFS/OS 信号，比较单药与双药背景；解释有害菌清除优于供体定植的机制假说；引入 TACITO 随机对照的数值改善与统计局限。强调单臂/历史对照偏倚。",
            "content_task_ids": ["C0052", "C0053", "C0054"],
            "source_handles": []
          },
          {
            "unit_id": "Ch5_W2",
            "title": "难治人群：FMT 的生物学屏障与阴性结果",
            "writing_arrangement": "报告 MITRIC 的 ORR 0% 与 PFS 数据；解析定植短暂、基线髓系偏倚、高 IL-8 与免疫微环境固化；补充 Kim 等低响应数据，说明 FMT 难以普遍克服已建立耐药。",
            "content_task_ids": ["C0055", "C0056", "C0057"],
            "source_handles": []
          },
          {
            "unit_id": "Ch5_W3",
            "title": "LBPs/定义菌群：标准化优势、早期信号与开发困境",
            "writing_arrangement": "评估 CBM588 对肠道稳态的微生物学合理性；报告 MRx0518 安全性与初步疗效/机制假说；概述 MET4 等定义菌群的免疫反应、监管与实施困难。强调疗效终点仍为探索性。",
            "content_task_ids": ["C0058", "C0059", "C0060"],
            "source_handles": []
          },
          {
            "unit_id": "Ch5_W4",
            "title": "干预安全性：方案背景与供体特征的情境依赖",
