{
  "guide": {
    "schema_version": "optomind.guided_body_guide.v1",
    "manuscript_guide": "全文按“临床关联证据→免疫机制→代谢物中介→外部干扰→干预转化→毒性管理→方法学未来”推进。Ch1 主讲观察性关联的强度、异质性、外部修饰与证据阶梯；Ch2 主讲免疫机制链条并严格区分动物因果与人类关联；Ch3 主讲代谢物分子靶点与 TME 浓度缺口；Ch4 主讲抗生素/PPI/饮食等外部暴露的时机、剂量与癌种差异；Ch5 主讲 FMT/LBP/益生菌干预的证据等级、初治与难治差异、安全性边界；Ch6 主讲 irAE 微生物预测、疗效-毒性耦合/解耦与供体-方案情境安全；Ch7 主讲技术标准化、因果推断、III 期缺口与未来设计。重复案例采用分层复用：FMT-LUMINate 在 Ch1 作为证据阶梯案例，在 Ch2 作为人类伴随机制线索，在 Ch5 作为初治干预主讲案例，在 Ch6 作为供体毒性主讲案例；MITRIC 在 Ch1 作为阴性对照，在 Ch5 作为难治人群主讲案例；JCOG2007 在 Ch1 主讲方案特异性，在 Ch4 作为化疗时序修饰对照，在 Ch5 仅作背景。写作中保留阴性结果、条件限定、样本量限制与证据等级标注。全文实际引用目标为去重后不少于 150 篇；相关来源可在背景、方法、解释与比较中共同引用，合并论述时保留各自支撑作用。",
    "chapters": [
      {
        "chapter_id": "Ch1",
        "title": "实体瘤中肠道微生物组与 ICI 疗效的临床关联证据",
        "writing_arrangement": "本章先建立跨癌种观察性关联的总体图景，再立即用统计与反例限制“通用标志物”推断；随后引入外部药物暴露与治疗方案作为修饰变量，再转向纵向动态对基线快照的补充，最后以证据阶梯收束。解释顺序为：共性信号→异质性与无通用标志物→方案/暴露修饰→纵向动态→证据等级与转化边界。写作中每次引用具体数字时标明研究设计、癌种、治疗方案与时间窗；对 FMT-LUMINate、MITRIC、MIMic、JCOG2007 等案例只作本章所需的证据等级展示，不展开后续章节的机制与安全性细节。",
        "required_content": [
          "章首用一段说明本章只评估临床关联与证据等级，机制细节留给 Ch2/Ch3，外部因素系统展开留给 Ch4，干预试验系统评价留给 Ch5。",
          "在证据阶梯单元中明确表格承担的比较：试验阶段、目标人群、干预策略、疗效结果与关键局限；正文解释表格而不是重复表格。",
          "保留 P0289、P0275、P0270、P0327 等阴性或反例证据，避免将观察性关联写成普适结论。"
        ],
        "source_handles": [],
        "writing_units": [
          {
            "unit_id": "Ch1_W1",
            "title": "跨癌种关联图谱与无通用标志物的统计依据",
            "writing_arrangement": "先写黑色素瘤、NSCLC、RCC 等队列中反复出现的分类学与功能信号，再写 HCC、mCRPC、结直肠癌等信号失效或反转，随后用跨队列 PERMANOVA、机器学习泛化差、肠型特异性与功能趋同解释为何没有普适单一标志物。最后以 JCOG2007 的方案特异性作为过渡，说明关联方向受治疗方案修饰。",
            "content_task_ids": ["C0001", "C0002", "C0003"],
            "source_handles": []
          },
          {
            "unit_id": "Ch1_W2",
            "title": "外部药物暴露与宿主背景对关联强度的修饰",
            "writing_arrangement": "本单元量化抗生素与 PPIs 的效应量和时间窗，比较不同癌种与人群中的阳性/阴性结果，再讨论联合方案对微生物效应方向的反转或放大。最后写校正必要性、指示偏倚与残余偏倚，为 Ch4 的系统展开留出接口但不重复其全部机制。",
            "content_task_ids": ["C0004", "C0005", "C0006"],
            "source_handles": []
          },
          {
            "unit_id": "Ch1_W3",
            "title": "基线快照局限与纵向动态的预测价值",
            "writing_arrangement": "从基线单次采样无法捕捉治疗诱导生态重塑写起，比较新辅助与晚期疾病中稳定性/多样性信号的差异；再写纵向动态（有害菌丢失、定植、稳定性丧失、多组学轨迹）的预测价值；最后写采样频率、存储、标准化与参考值缺失等方法学障碍。此处只作临床观察层面的动态证据，不展开机制。",
            "content_task_ids": ["C0007", "C0008", "C0009"],
            "source_handles": []
          },
          {
            "unit_id": "Ch1_W4",
            "title": "证据阶梯、阴性干预与安全信号的情境依赖",
            "writing_arrangement": "总结观察性证据最强、概念验证干预异质性大、Phase III 缺失的证据阶梯；比较 FMT-LUMINate 阳性、MITRIC 阴性与早期综述/荟萃证据；用表格呈现主要干预试验设计与局限；最后用安全信号仅在双 ICI 背景出现说明方案调节，并过渡到下一章机制。",
            "content_task_ids": ["C0010", "C0011", "C0012", "C0013"],
            "source_handles": []
          }
        ]
      },
      {
        "chapter_id": "Ch2",
        "title": "微生物调节 ICI 疗效的免疫学机制",
        "writing_arrangement": "本章建立“微生物信号→先天识别→适应性启动→屏障/易位/髓系重塑→肿瘤类型与模型边界”的机制链。每个机制节点都按“动物因果证据→人类关联/伴随证据→外推限制”组织。与 Ch1 的衔接是：Ch1 已证明关联存在但非普适，本章解释可能机制；与 Ch3 的分工是：本章写细胞与受体通路，不深入代谢物浓度/剂量；与 Ch5/Ch6 的分工是：本章不评价干预试验成败，只在必要处引用人类试验作为伴随证据。",
        "required_content": [
          "每个机制段落标注证据类型：小鼠因果、体外功能、人类宏基因组关联、人类干预伴随观察。",
          "保留 CRC、PDAC、消化道肿瘤等语境差异，防止 PRR/STING/屏障机制被写成单向促免疫。",
          "表格承担不同肿瘤类型中关键微生物特征、机制通路、证据类型与来源比较；正文解释差异含义。"
        ],
        "source_handles": [],
        "writing_units": [
          {
            "unit_id": "Ch2_W1",
            "title": "先天识别与 DC 启动：结构、受体与检查点语气",
            "writing_arrangement": "先写 LPS 酰化状态、MAMPs/TLR/NOD2 等结构-受体语境，说明“有菌不等于激活”；再写 DC 亚群成熟、迁移与 STING/IFN-β 轴；最后写微生物调节 DC PD-L2/RGMb 等检查点语气。人类证据用黑色素瘤 lpxM 关联、FMT 后 CD8+ 增加与肿瘤内微生物观察作对照，强调不能直接外推小鼠因果。",
            "content_task_ids": ["C0014", "C0015", "C0016"],
            "source_handles": []
          },
          {
            "unit_id": "Ch2_W2",
            "title": "适应性免疫启动：分子模拟、T 细胞 priming 与亚群平衡",
            "writing_arrangement": "先写分子模拟与交叉反应性 CD8+ 激活，区分小鼠功能回补与人类生物信息学/体外证据；再写 T 细胞 priming、Th17/Treg、非经典 T 细胞与耗竭调控。代谢物只作为微环境因素点名，详细分子靶点留给 Ch3。",
            "content_task_ids": ["C0017", "C0018"],
            "source_handles": []
